// Generated by scripts/sync-help.mjs from pzza-code-web/components/home/AppUI.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Building blocks of the PzzaCode desktop UI: the window, its top bar brand
 * and the session tile, ported from the app's own components (src/App.tsx,
 * src/grid/Canvas.tsx, src/ui/DeviceIcon.tsx, src/icons/AgentIcon.tsx) with
 * their markup, class names, icons and titles, and styled by the app's own
 * stylesheet (app.css). Only the native window frame is drawn by hand
 * (home.css), as the app has no markup for it.
 */
import type { CSSProperties, ReactNode } from "react";
import {
  Copy,
  EyeOff,
  FileCode,
  FolderGit2,
  FolderInput,
  History,
  Maximize2,
  Mic,
  SquareTerminal,
  X,
  type LucideIcon,
} from "lucide-react";
import { DeviceIcon } from "../docs/settings/DeviceIcon";
import { TileFooter, type TileFooterInfo } from "../docs/git/TileFooter";
import { AGENTS, catalogAgent, type AgentId } from "./agents";
import { useTileSlot } from "./Interactive";

/* ------------------------------------------------------------ agent marks -- */

/** A catalog agent, or a plain shell. */
export type Agent = AgentId | "terminal";

export function agentLabel(agent: Agent): string {
  return agent === "terminal" ? "Terminal" : catalogAgent(agent).label;
}

// The app tints the live session icon of these three; every other agent's
// mark takes the surrounding text colour (src/sessionMeta.ts, AGENT_COLORS).
const AGENT_TINT: Partial<Record<Agent, string>> = { claude: "#D97757", codex: "#10A37F", opencode: "#94A3B8" };

const markId = (agent: AgentId) => `agent-mark-${agent}`;

/**
 * The vendors' marks as SVG symbols. A page that shows AgentMark renders this
 * once, and every mark points at its symbol instead of repeating the path
 * data (a mark can appear dozens of times on the homepage).
 */
export function AgentMarkSprite() {
  return (
    <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden="true" focusable="false">
      {AGENTS.map(({ id }) => ({ id, logo: catalogAgent(id).logo })).map(({ id, logo }) =>
        logo.kind === "brand" ? (
          <symbol key={id} id={markId(id)} viewBox={logo.viewBox}>
            <g fill="currentColor" fillRule={logo.fillRule}>
              {logo.paths.map((path) =>
                path.strokeWidth ? <path key={path.d} d={path.d} stroke="currentColor" strokeWidth={path.strokeWidth} /> : <path key={path.d} d={path.d} />,
              )}
            </g>
          </symbol>
        ) : null,
      )}
    </svg>
  );
}

/**
 * An agent's one-colour mark, drawn like the app's AgentIcon: the vendor's
 * vector where it has one (from AgentMarkSprite), otherwise a rounded
 * monogram. `tinted` uses the colour of the app's live session icon.
 */
export function AgentMark({ agent, size = 14, tinted = false }: { agent: Agent; size?: number; tinted?: boolean }) {
  if (agent === "terminal") return <SquareTerminal size={size} strokeWidth={1.9} aria-hidden="true" />;
  const logo = catalogAgent(agent).logo;
  const style = tinted && AGENT_TINT[agent] ? { color: AGENT_TINT[agent] } : undefined;
  if (logo.kind === "brand") {
    return (
      <svg width={size} height={size} style={style} aria-hidden="true">
        <use href={`#${markId(agent)}`} />
      </svg>
    );
  }
  // Two letters only where they stay legible, like the app.
  const letters = size < 20 ? logo.monogram.slice(0, 1).toUpperCase() : logo.monogram;
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" style={style} aria-hidden="true">
      <rect x="1.75" y="1.75" width="20.5" height="20.5" rx="6" stroke="currentColor" strokeWidth="1.5" />
      <text
        x="12"
        y="12.5"
        fill="currentColor"
        textAnchor="middle"
        dominantBaseline="central"
        fontSize={letters.length > 1 ? 10.5 : 13}
        fontWeight={650}
        letterSpacing={letters.length > 1 ? -0.4 : 0}
        style={{ fontFamily: "inherit" }}
      >
        {letters}
      </text>
    </svg>
  );
}

/* --------------------------------------------------------------- window --- */

/**
 * The desktop window: the native frame (rounded edge, shadow, vibrancy and
 * the traffic lights, drawn in home.css) around the app's root, `.app`.
 * `tauri-mac` is the class the app puts on its root on macOS, where the
 * overlay title bar insets the top bar clear of the traffic lights.
 */
export function Window({
  style,
  children,
}: {
  style: CSSProperties;
  children: ReactNode;
}) {
  return (
    <div className="pz-window tauri-mac" style={style}>
      <div className="app">{children}</div>
      <div className="pz-lights" aria-hidden="true">
        <i />
        <i />
        <i />
      </div>
    </div>
  );
}

/** The top bar (src/App.tsx): Brand, WorkspaceTabs and ToolsBar go inside. */
export function TopBar({ children }: { children: ReactNode }) {
  return <header className="topbar">{children}</header>;
}

/** The top bar's brand (src/App.tsx). `version` is shown as given, e.g. "v0.2.94". */
export function Brand({ version }: { version?: string }) {
  return (
    <div className="brand">
      <span className="brand-mark">
        {/* eslint-disable-next-line @next/next/no-img-element */}
        <img src="/pzzacode.svg" alt="" className="brand-logo" />
      </span>
      <span className="brand-name">PzzaCode</span>
      {version ? <span className="brand-version">{version}</span> : null}
    </div>
  );
}

/** A keycap badge (the app's `.kbd`). */
export function Kbd({ children }: { children: ReactNode }) {
  return <kbd className="kbd">{children}</kbd>;
}

/* ----------------------------------------------------------------- tile --- */

/** TileStatus (src/sessionMeta.ts): the header's status dot. */
export type Stat = "idle" | "active" | "notify" | "failed";

export interface DeviceInfo {
  name: string;
  os: "mac" | "linux";
}

export interface StripInfo {
  session: string;
  branch?: string;
  dirty?: boolean;
  ahead?: number;
  pr?: number;
  worktree?: boolean;
  path: string;
  started?: string;
}

/** The device pill of a tile header (SessionHeader in src/grid/Canvas.tsx). */
export function Device({ device }: { device: DeviceInfo }) {
  return (
    <span className="tile-device" title={`Running on ${device.name}`}>
      <DeviceIcon os={device.os} size={11} />
      <span className="tile-device-name">{device.name}</span>
    </span>
  );
}

/**
 * The tile's live session icon (src/ui/LiveSessionIcon.tsx): the running
 * agent's mark in its colour, or the terminal icon for a shell, with the
 * tooltip the app shows while the effective model is not known.
 */
function SessionIcon({ agent }: { agent: Agent }) {
  const launcher = agent === "terminal" ? "zsh" : agentLabel(agent);
  return (
    <span title={`Launcher: ${launcher}. Effective model unavailable.`} style={{ display: "inline-flex", color: AGENT_TINT[agent] }}>
      {agent === "terminal" ? <SquareTerminal size={14} /> : <AgentMark agent={agent} size={14} />}
    </span>
  );
}

type HeaderGroup = "input" | "git" | "session" | "view" | "close";

interface HeaderButton {
  id: string;
  group: HeaderGroup;
  icon: LucideIcon;
  title: string;
  label?: string;
  danger?: boolean;
  dialog?: boolean;
  pressed?: boolean;
}

/**
 * A terminal tile's header buttons in the app's order and groups (HEADER_ACTIONS
 * and Canvas's sessionParts in src/grid/Canvas.tsx), for a session whose folder
 * is known, with no checkpoints saved yet, not maximized.
 */
function headerButtons(codeOpen: boolean): HeaderButton[] {
  const code = codeOpen ? "Back to terminal" : "Code editor";
  return [
    { id: "mic", group: "input", icon: Mic, title: "Start dictation" },
    { id: "code", group: "input", icon: FileCode, title: code, pressed: codeOpen },
    {
      id: "worktrees",
      group: "git",
      icon: FolderGit2,
      title: "Worktrees\nThe Git worktrees of this session's repository, or of the repositories in its folder",
      label: "Worktrees",
      dialog: true,
    },
    { id: "checkpoints", group: "git", icon: History, title: "Checkpoints\nNone in this folder yet. Click to save one", label: "Checkpoints", dialog: true },
    { id: "move", group: "session", icon: FolderInput, title: "Move to workspace" },
    { id: "duplicate", group: "session", icon: Copy, title: "Duplicate session" },
    { id: "fullscreen", group: "view", icon: Maximize2, title: "Maximize (double-click the header)", label: "Maximize" },
    { id: "hide", group: "view", icon: EyeOff, title: "Hide (keeps running)" },
    { id: "close", group: "close", icon: X, title: "Terminate", danger: true },
  ];
}

/**
 * The tile header (SessionHeader in src/grid/Canvas.tsx): status dot, session
 * icon, title, ⌘n badge, device pill and the button groups. The mic shows only
 * with dictation set up (it is off by default), like the app, which still keeps
 * its empty slot. `pz-head` and `pz-tile-btn` carry no style; BroadcastScene
 * finds the header and its buttons by them.
 */
export function TileHead({
  title,
  agent,
  stat = "idle",
  kbd,
  device,
  codeOpen = false,
  dictation = false,
  headTitle,
}: {
  title: string;
  agent: Agent;
  stat?: Stat;
  kbd?: string;
  device: DeviceInfo;
  codeOpen?: boolean;
  /** Dictation is set up, so the header shows its mic button. */
  dictation?: boolean;
  /** A tooltip for the header itself. */
  headTitle?: string;
}) {
  const buttons = headerButtons(codeOpen);
  return (
    <div className="tile-head pz-head" title={headTitle}>
      <span className={`stat stat-${stat}`} title={stat} />
      <span className="tile-icon">
        <SessionIcon agent={agent} />
      </span>
      <span className="tile-title" title={`${title}\nClick to rename`}>
        {title}
      </span>
      {kbd ? (
        <kbd className="kbd tile-kbd" title="Activate">
          {kbd}
        </kbd>
      ) : null}
      <Device device={device} />
      <div className="tile-head-spacer" />
      <div className="tile-actions">
        {buttons.map((button, index) => {
          const { id, group, icon: Icon, title: tip, label, danger, dialog, pressed } = button;
          // A divider goes before the first button of every group but the first.
          const groupStart = index > 0 && buttons[index - 1].group !== group;
          return (
            <span key={id} className={`tile-action tile-action-${id}${groupStart ? " tile-action-group-start" : ""}`}>
              {id === "mic" && !dictation ? null : (
                <button
                  type="button"
                  className={`tile-btn pz-tile-btn${danger ? " tile-btn-danger" : ""}${pressed ? " tile-btn-on" : ""}`}
                  title={tip}
                  aria-label={label ?? tip}
                  aria-haspopup={dialog ? "dialog" : undefined}
                  aria-pressed={id === "fullscreen" ? false : undefined}
                >
                  <Icon size={id === "close" ? 14 : 13} aria-hidden={dialog ? true : undefined} />
                </button>
              )}
            </span>
          );
        })}
      </div>
    </div>
  );
}

/**
 * The tile footer (TileStatusStrip in src/grid/Canvas.tsx, ported in
 * TileFooter): the tmux session, the branch with its dirty, ahead and pull
 * request marks, a worktree's land actions, the folder and the start time.
 */
export function TileStrip({ s }: { s: StripInfo }) {
  const info: TileFooterInfo = {
    session: s.session,
    git: s.branch ? { branch: s.branch, dirty: s.dirty, ahead: s.ahead } : undefined,
    pr: s.pr ? { number: s.pr, state: "OPEN", checks: "passing" } : null,
    // The demo repositories have a remote, so the branch opens its page.
    web: true,
    agent: true,
    worktree: s.worktree ? { base: "main" } : undefined,
    path: s.path,
    started: s.started,
  };
  return <TileFooter info={info} />;
}

/**
 * A session tile (Canvas's tile in src/grid/Canvas.tsx). Inside an
 * ActiveCanvas it is active or inactive as the canvas says; on its own,
 * `inactive` gives it the inactive wash.
 */
export function Tile({
  title,
  agent,
  stat,
  kbd,
  device,
  strip,
  footer,
  inactive,
  selected,
  codeOpen,
  dictation,
  headTitle,
  bodyClass = "",
  style,
  className = "",
  children,
}: {
  title: string;
  agent: Agent;
  stat?: Stat;
  kbd?: string;
  device: DeviceInfo;
  strip?: StripInfo;
  /** A footer of the scene's own, in place of `strip` (e.g. a full TileFooter). */
  footer?: ReactNode;
  inactive?: boolean;
  /** Picked for a broadcast (shift-click on the header). */
  selected?: boolean;
  codeOpen?: boolean;
  dictation?: boolean;
  headTitle?: string;
  /** The app's tile-body modifier, e.g. tile-body-code-side-by-side while the editor is open. */
  bodyClass?: string;
  style?: CSSProperties;
  className?: string;
  children: ReactNode;
}) {
  const slot = useTileSlot();
  const isInactive = inactive ?? (slot ? !slot.active : false);
  const isActive = slot ? slot.active : false;
  const classes = ["tile", isActive ? "tile-active" : "", isInactive ? "tile-inactive" : "", selected ? "tile-selected" : "", className];
  return (
    <div className={classes.filter(Boolean).join(" ")} style={style}>
      <TileHead title={title} agent={agent} stat={stat} kbd={kbd} device={device} codeOpen={codeOpen} dictation={dictation} headTitle={headTitle} />
      <div className={`tile-body ${bodyClass}`.trim()}>{children}</div>
      {footer ?? (strip ? <TileStrip s={strip} /> : null)}
    </div>
  );
}

/* ------------------------------------------------------------- terminal --- */

/**
 * A tile's terminal: the app's `.term-surface`, holding the screen where the
 * app's xterm draws. `.pz-term` sets what xterm takes as options (font, cell
 * size) for the HTML screen; BroadcastScene scrolls it by that class.
 */
export function Term({ children }: { children: ReactNode }) {
  return (
    <div className="term-surface">
      <div className="pz-term">{children}</div>
    </div>
  );
}
